import{_ as l,l as r,o as a,c as o,v as n,p as i,x as t,d,i as p,S as P}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"PCIe 层次与 lane","description":"","frontmatter":{"title":"PCIe 层次与 lane","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pcie-lanes.md","filePath":"cs/pcie-lanes.md","lastUpdated":1789023840000}'),c={name:"cs/pcie-lanes.md"};function C(A,e,h,E,I,_){const s=r("Mermaid");return a(),o("div",null,[e[1]||(e[1]=n('<h1 id="pcie-层次与-lane" tabindex="-1">PCIe 层次与 lane <a class="header-anchor" href="#pcie-层次与-lane" aria-label="Permalink to &quot;PCIe 层次与 lane&quot;">​</a></h1><div class="epigraph"><p>PCIe 不是共享并行总线：点对点串行 lane 组成链路，分层为物理、数据链路与事务，设备各占自己的宽度。</p><footer>—— 据 PCI-SIG PCI Express Base Specification；Hennessy and Patterson, CA:AQA；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/hdd-geometry">上一课</a>把块设备停在内部几何。组成课的<a href="/cs/bus-mmio">总线与 MMIO</a> 是共享地址数据总线教学模型。缺口是当代互连 <strong>PCIe</strong>：lane、链路宽度 ×N、分层，让 SSD、GPU、网卡接到 CPU 根复合体。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PCI 并行总线仲裁、反射、频率上不去。PCIe：每 lane 差分串行，×1/×4/×16 并行多 lane。分层：物理层（串扰、训练、8b/10b 或 128b/130b）、数据链路（ACK/重传、DLLP）、事务层（TLP，下一课）。缺口不是再画教学总线，而是<strong>点对点交换机</strong>把根端口接到端点。</p><p>链路训练协商速率与宽度。热插拔与电源状态点名。本课不把 SerDes 模拟前端画成光刻。</p><h3 id="lane-不是「内存通道」" tabindex="-1">lane 不是「内存通道」 <a class="header-anchor" href="#lane-不是「内存通道」" aria-label="Permalink to &quot;lane 不是「内存通道」&quot;">​</a></h3><p>DRAM 通道有命令/地址/数据时序；PCIe lane 是包交换串行链路。把 ×16 当成另一条 DDR 通道，一致性与地址译码会错——设备用 BAR 映射，不是 JEDEC 行地址。HBM 更不是 PCIe。</p><p><span class="marginnote">PCI-SIG 基规范是权威。CA:AQA 与 COD 讨论 I/O 互连演进。本课用规范层次，不背每代 GT/s 表当作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>根复合体发出配置与内存 TLP。交换机基于地址/ID 路由。端点（SSD 控制器、NIC）实现 BAR。带宽粗算：每 lane 有效速率 × 宽度 × 方向（全双工）。开销：编码、DLLP、TLP 头，使有效载荷低于标称。</p>',11)),(a(),i(P,null,{default:t(()=>[p(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RC%5B%22%E6%A0%B9%E5%A4%8D%E5%90%88%E4%BD%93%22%5D%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%20lane%22%5D%0A%20%20PHY%20--%3E%20DL%5B%22%E6%95%B0%E6%8D%AE%E9%93%BE%E8%B7%AF%20ACK%22%5D%0A%20%20DL%20--%3E%20TL%5B%22%E4%BA%8B%E5%8A%A1%E5%B1%82%20TLP%22%5D%0A%20%20TL%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ATLP%20%E7%B1%BB%E5%9E%8B%E4%B8%8E%20BAR%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<p>NVMe SSD 是端点，内部再接 NAND 并行；PCIe 只负责到主机内存/CPU。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课事务：Cfg/Mem/IO/Message，BAR 窗口把 MMIO 落到设备寄存器。MSI-X 用 TLP 写中断。本课先把「串行分层链路」钉住，替代教学共享总线的频率神话。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 CXL 全缓存一致协议（点名为 PCIe 物理上的近亲即可）。不把以太网 MAC 当 PCIe。不写光模块。不进入大模型多卡拓扑品牌。</p><p>后课默认：PCIe 是分层点对点串行互连；宽度用 lane 数表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享并行 PCI 被点对点 PCIe 替代。</li><li>物理 / 数据链路 / 事务三层；lane 可聚合。</li><li>下一课才是 TLP 与 BAR 地址窗口。</li><li>出处：PCI-SIG PCIe Base Spec；Hennessy and Patterson, CA:AQA；Patterson and Hennessy, COD。</li></ul>',8))])}const D=l(c,[["render",C]]);export{m as __pageData,D as default};
